"""Evidence pack: a Markdown report a human can read and sign off."""

from __future__ import annotations

import subprocess
from pathlib import Path

from .. import __version__
from .analysis import Context, build_matrix, find_gaps
from .model import Gap, Matrix, Status
from .state import load_issues, load_reviews, load_suggestions

ICON = {
    Status.REVIEWED: "✅",
    Status.VERIFIED: "🟢",
    Status.WEAKLY_VERIFIED: "🟡",
    Status.NOT_RUN: "⚪",
    Status.FAILING: "🔴",
    Status.NOT_VERIFIED: "🟠",
    Status.NOT_IMPLEMENTED: "⛔",
}

DISCLAIMER = (
    "This report is generated by reqtrace-mcp, an open-source tool inspired by public "
    "software-assurance practice (requirements traceability, independent verification, "
    "structural coverage). It is not a qualified tool and this report does not by itself "
    "satisfy any certification objective."
)


def _git_rev(root: Path) -> str:
    try:
        out = subprocess.run(
            ["git", "rev-parse", "--short", "HEAD"],
            cwd=root,
            capture_output=True,
            text=True,
            timeout=10,
        )
        dirty = subprocess.run(
            ["git", "status", "--porcelain"], cwd=root, capture_output=True, text=True, timeout=10
        ).stdout.strip()
        rev = out.stdout.strip() or "no commits"
        return rev + (" (uncommitted changes)" if dirty else "")
    except (OSError, subprocess.SubprocessError):
        return "not a git repository"


def _pct(v: float | None) -> str:
    return "n/a" if v is None else f"{v:.0f}%"


def _esc(s: str) -> str:
    return s.replace("|", "\\|").replace("\n", " ")


def render_markdown(
    ctx: Context, matrix: Matrix | None = None, gaps: list[Gap] | None = None
) -> str:
    m = matrix or build_matrix(ctx)
    g = gaps if gaps is not None else find_gaps(ctx, m)
    counts = m.counts()
    total = len(m.requirements)
    ok = counts["VERIFIED"] + counts["REVIEWED"]
    lines = [
        "# Verification evidence report",
        "",
        f"- Generated: {m.generated_at}",
        f"- Repository revision: `{_git_rev(ctx.cfg.root)}`",
        f"- Test run: `{m.run_id or 'none'}`"
        + (" — **stale: code changed since this run**" if ctx.results_stale else ""),
        f"- Tool: reqtrace-mcp {__version__}",
        "",
        "## Summary",
        "",
        f"**{ok} of {total} requirements verified** ({counts['REVIEWED']} also signed off by "
        f"a human). Open gaps: {len(g)}. Unrequired code items: {len(m.unrequired_code)}.",
        "",
        "| Status | Count |",
        "|---|---|",
        *[f"| {ICON[s]} {s.value} | {counts[s.value]} |" for s in Status if counts[s.value]],
        "",
        "## Requirements",
        "",
        "| Req | Status | Implemented by | Verified by | Results | Stmt cov | Branch cov |",
        "|---|---|---|---|---|---|---|",
    ]
    for t in m.requirements:
        res = ", ".join(f"{v}" for v in sorted(set(t.test_results.values()))) or "—"
        cov = t.coverage
        lines.append(
            f"| **{t.requirement.id}** {_esc(t.requirement.title)} | {ICON[t.status]} "
            f"{t.status.value} | {'<br>'.join(f'`{i}`' for i in t.implemented_by) or '—'} | "
            f"{'<br>'.join(f'`{i}`' for i in t.verified_by) or '—'} | {res} | "
            f"{_pct(cov.statement_pct) if cov else 'n/a'} | "
            f"{_pct(cov.branch_pct) if cov else 'n/a'} |"
        )
    lines += ["", "## Requirement text", ""]
    for t in m.requirements:
        r = t.requirement
        lines.append(f"**{r.id}** {r.title} — {r.text}")
        lines += [f"  - acceptance: {a}" for a in r.acceptance]
        if t.review:
            lines.append(f"  - review: {t.review}")
        lines.append("")
    lines += ["## Open gaps", ""]
    if not g:
        lines.append("None.")
    for gap in g:
        where = f" `{gap.location}`" if gap.location else ""
        lines.append(
            f"- **{gap.kind}** {gap.req_id or ''}{where}: {_esc(gap.detail)} → {gap.next_action}"
        )
    lines += ["", "## Unrequired code", ""]
    lines += [f"- `{u}`" for u in m.unrequired_code] or ["None."]
    lines += ["", "## Agent-suggested links (not trusted until a human accepts them)", ""]
    sugg = load_suggestions(ctx.cfg)
    lines += [
        f"- {s.id} [{s.status}] {s.req_id} {s.kind} `{s.target}`: {_esc(s.rationale)}" for s in sugg
    ] or ["None."]
    lines += ["", "## Requirement issues raised", ""]
    lines += [
        f"- {i.id} {i.req_id} [{i.kind}] by {i.raised_by}: {_esc(i.description)}"
        for i in load_issues(ctx.cfg)
    ] or ["None."]
    lines += ["", "## Review ledger (append-only)", ""]
    lines += [
        f"- {r.timestamp} {r.req_id} **{r.decision}** by {r.reviewer} "
        f"(hash `{r.content_hash}`): {_esc(r.rationale)}"
        for r in load_reviews(ctx.cfg)
    ] or ["No reviews recorded."]
    lines += ["", "---", "", f"*{DISCLAIMER}*", ""]
    return "\n".join(lines)


def write_evidence(ctx: Context) -> tuple[Path, Matrix, list[Gap]]:
    m = build_matrix(ctx)
    g = find_gaps(ctx, m)
    out_dir = ctx.cfg.state_dir / "evidence"
    out_dir.mkdir(parents=True, exist_ok=True)
    path = out_dir / "evidence.md"
    path.write_text(render_markdown(ctx, m, g), encoding="utf-8")
    (out_dir / "matrix.json").write_text(m.model_dump_json(indent=1), encoding="utf-8")
    return path, m, g
